#include "ecos_studio/input.hpp"
#include <cmath>
#include <iostream>
namespace {int failures=0;void check(bool ok,const char* m){if(!ok){std::cerr<<"FAIL: "<<m<<'\n';++failures;}}
void test_keys(){using namespace ecos::studio;InputState input;check(static_cast<bool>(input.key_event(InputKey::W,InputAction::Press)),"accepts key press");check(input.snapshot().down(InputKey::W),"snapshot reports held key");(void)input.key_event(InputKey::W,InputAction::Release);check(!input.snapshot().down(InputKey::W),"release clears held key");check(!input.key_event(InputKey::Unknown,InputAction::Press),"rejects unknown key");}
void test_mouse_and_frame(){using namespace ecos::studio;InputState input;input.mouse_move(10,20);input.mouse_move(13,16);input.scroll(0,1);auto s=input.snapshot();check(s.mouse_delta_x==3&&s.mouse_delta_y==-4,"accumulates mouse delta");check(s.scroll_y==1,"accumulates scroll");input.end_frame();s=input.snapshot();check(s.mouse_delta_x==0&&s.scroll_y==0,"clears frame deltas");input.mouse_move(NAN,4);check(input.snapshot().mouse_x==13,"ignores non-finite cursor input");}
void test_buttons_quit(){using namespace ecos::studio;InputState input;check(static_cast<bool>(input.mouse_button_event(0,InputAction::Press)),"accepts mouse button");check(input.snapshot().mouse_buttons[0],"tracks mouse button");check(!input.mouse_button_event(8,InputAction::Press),"rejects invalid button");input.request_quit();check(input.snapshot().quit_requested,"tracks quit request");input.reset();check(!input.snapshot().quit_requested&&!input.snapshot().mouse_buttons[0],"reset clears input state");}
}
int main(){test_keys();test_mouse_and_frame();test_buttons_quit();if(failures){std::cerr<<failures<<" input tests failed.\n";return 1;}std::cout<<"ECOS Studio input tests passed.\n";return 0;}